// Combine the three IP feeds into one item of {source, ip, details} rows for
// ip_sightings. A feed whose request failed carries an `error` field and is
// skipped, so one vendor being down never blocks the others. IPv4 only.
const rows = new Map();

function add(source, rawIp, details) {
  const parts = String(rawIp ?? '').trim().split('.');
  if (parts.length !== 4 || !parts.every((p) => /^\d{1,3}$/.test(p) && Number(p) <= 255)) return;
  // DShield sometimes zero-pads octets (079.124.059.078).
  const ip = parts.map(Number).join('.');
  rows.set(`${source}|${ip}`, { source, ip, details });
}

const ok = (items) => items.filter((it) => !it.json.error);

for (const { json: d } of ok($('DShield: top attackers').all())) {
  add('dshield', d.ip, { attacks: d.attacks, count: d.count, firstseen: d.firstseen, lastseen: d.lastseen });
}

for (const { json: f } of ok($('Feodo: C2 blocklist').all())) {
  add('feodo', f.ip_address, {
    port: f.port, status: f.status, malware: f.malware, as_name: f.as_name,
    country: f.country, first_seen: f.first_seen, last_online: f.last_online,
  });
}

for (const { json: b } of ok($('blocklist.de: all').all())) {
  for (const line of String(b.data ?? '').split('\n')) add('blocklistde', line, {});
}

const counts = {};
for (const r of rows.values()) counts[r.source] = (counts[r.source] ?? 0) + 1;

return rows.size ? [{ json: { counts, rows: [...rows.values()] } }] : [];

// AbuseIPDB blacklist ({meta, data: [{ipAddress, abuseConfidenceScore, ...}]})
// into ip_sightings rows. A failed download carries `error` and yields nothing.
const rows = [];
for (const { json } of $input.all()) {
  if (json.error || !Array.isArray(json.data)) continue;
  for (const d of json.data) {
    if (!/^\d{1,3}(\.\d{1,3}){3}$/.test(d.ipAddress ?? '')) continue; // IPv4 only, like the other feeds
    rows.push({
      source: 'abuseipdb',
      ip: d.ipAddress,
      details: { score: d.abuseConfidenceScore, country: d.countryCode, last_reported: d.lastReportedAt },
    });
  }
}
return rows.length ? [{ json: { rows } }] : [];

// IPv4 indicators from OTX subscribed pulses into ip_sightings rows. One row
// per IP, listing up to 5 of the pulses that mention it.
const byIp = new Map();
for (const { json } of $input.all()) {
  if (json.error || !Array.isArray(json.results)) continue;
  for (const pulse of json.results) {
    for (const ind of pulse.indicators ?? []) {
      if (ind.type !== 'IPv4') continue;
      const row = byIp.get(ind.indicator) ?? { source: 'otx', ip: ind.indicator, details: { pulses: [] } };
      if (row.details.pulses.length < 5) {
        row.details.pulses.push({
          id: pulse.id, name: pulse.name, author: pulse.author_name,
          tags: (pulse.tags ?? []).slice(0, 10), modified: pulse.modified,
        });
      }
      byIp.set(ind.indicator, row);
    }
  }
}
return byIp.size ? [{ json: { rows: [...byIp.values()] } }] : [];
